#!/usr/bin/env bash
# Known-answer vectors for sys::tls's signature verification, signed by
# OpenSSL itself (3.0.13 when committed) with the M6.5 fixture keys
# (tests/differential/m6/m65_tls/certs). Re-run to regenerate vectors.txt;
# the signatures are randomized (ECDSA, PSS), so the file changes, and the
# tests only need each line to verify (or, for `bad`, not to).
#
# vectors.txt, one per line: NAME SCHEME CERT-DER-HEX MSG-HEX SIG-HEX EXPECT
# EXPECT is `ok` or `bad` (OpenSSL's TLS verification would refuse it).
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CERTS="$HERE/../../../../../tests/differential/m6/m65_tls/certs"
W="$(mktemp -d)"; trap 'rm -rf "$W"' EXIT
printf 'the TLS 1.2 ServerKeyExchange params, or a TLS 1.3 CertificateVerify input' > "$W/msg"
MSG=$(od -An -v -tx1 "$W/msg" | tr -d ' \n')
der() { openssl x509 -in "$CERTS/$1.crt" -outform DER | od -An -v -tx1 | tr -d ' \n'; }
sig() { openssl dgst "-$1" -sign "$CERTS/$2.key" "${@:3}" "$W/msg" | od -An -v -tx1 | tr -d ' \n'; }
{
  echo "# generated by gen_vectors.sh with $(openssl version)"
  for h in sha256 sha384 sha512; do
    echo "rsa-pkcs1-$h RSA_PKCS1_${h^^} $(der rsa2048) $MSG $(sig $h rsa2048) ok"
    echo "rsa-pss-$h RSA_PSS_${h^^} $(der rsa2048) $MSG $(sig $h rsa2048 -sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:digest) ok"
  done
  echo "rsa-pss-salt0 RSA_PSS_SHA256 $(der rsa2048) $MSG $(sig sha256 rsa2048 -sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:0) bad"
  echo "rsa-pss-as-pkcs1 RSA_PKCS1_SHA256 $(der rsa2048) $MSG $(sig sha256 rsa2048 -sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:digest) bad"
  echo "rsa512-pkcs1 RSA_PKCS1_SHA256 $(der rsa512) $MSG $(sig sha256 rsa512) ok"
  echo "ecdsa-p256 ECDSA_NISTP256_SHA256 $(der ecp256) $MSG $(sig sha256 ecp256) ok"
  echo "ecdsa-p384 ECDSA_NISTP384_SHA384 $(der ecp384) $MSG $(sig sha384 ecp384) ok"
  echo "ecdsa-p521 ECDSA_NISTP521_SHA512 $(der ecp521) $MSG $(sig sha512 ecp521) ok"
  # TLS 1.2: the scheme names the hash; the curve is the key's.
  echo "ecdsa-p384-sha256 ECDSA_NISTP256_SHA256 $(der ecp384) $MSG $(sig sha256 ecp384) tls12"
  echo "ecdsa-p521-sha256 ECDSA_NISTP256_SHA256 $(der ecp521) $MSG $(sig sha256 ecp521) tls12"
  echo "ed25519 ED25519 $(der ed25519) $MSG $(openssl pkeyutl -sign -inkey "$CERTS/ed25519.key" -rawin -in "$W/msg" | od -An -v -tx1 | tr -d ' \n') ok"
} > "$HERE/vectors.txt"
